<script>
(()=>{document.querySelectorAll('[data-dialog-open]').forEach(button=>button.onclick=()=>document.getElementById(button.dataset.dialogOpen).showModal());document.querySelectorAll('[data-dialog-close]').forEach(button=>button.onclick=()=>document.getElementById(button.dataset.dialogClose).close());document.querySelectorAll('[data-auto-open]').forEach(dialog=>dialog.showModal());document.querySelectorAll('[data-directory-url]').forEach(row=>{row.addEventListener('click',event=>{if(!event.target.closest('a,button,input,select'))location.href=row.dataset.directoryUrl;});row.addEventListener('keydown',event=>{if(event.target===row&&(event.key==='Enter'||event.key===' ')){event.preventDefault();location.href=row.dataset.directoryUrl;}});});const toggle=document.getElementById('includeVehicle');if(toggle){const sync=()=>{document.getElementById('newCustomerVehicle').disabled=!toggle.checked;document.getElementById('saveCustomerJob').disabled=!toggle.checked;};toggle.addEventListener('change',sync);sync();}})();
</script>
